export function buildAchievementViewModel(achievements = []) {
  const rows = (Array.isArray(achievements) ? achievements : []).map(i => ({ ...i, unlocked: Boolean(i?.unlocked) }));
  const unlocked = rows.filter(i => i.unlocked);
  const locked = rows.filter(i => !i.unlocked);
  return {
    total: rows.length,
    unlockedCount: unlocked.length,
    remainingCount: locked.length,
    unlocked,
    locked
  };
}
